<!DOCTYPE html>
<html>
<head>
  <title>Billiards Game</title>
  <style>
    body { margin: 0; overflow: hidden; background-color: #333; }
    canvas { display: block; }
    .aim-line { position: absolute; z-index: 1; border: 1px dashed white; }
  </style>
</head>
<body>
  <canvas id="gameCanvas"></canvas>

  <div style="position: absolute; top: 10px; left: 10px; color: white; font-family: sans-serif;">
    Instructions: Click and drag the cue ball to aim. Release to shoot! Longer drags mean harder shots.
  </div>

  <script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    canvas.width = 800;
    canvas.height = 600;
    const sim = {
      W: 800,
      H: 600,
      R: 15,
      balls: [],
      reset: function(balls) {
        this.balls = balls.map(ball => ({ x: ball.x * this.W / 100, y: ball.y * this.H / 100, vx: ball.vx * this.W / 100, vy: ball.vy * this.H / 100, cue: ball.cue }));
      },
      step: function(dt) {
        for (const ball of this.balls) {
          if (!ball.cue) continue;

          let x = ball.x;
          let y = ball.y;
          let vx = ball.vx;
          let vy = ball.vy;

          // Collision with walls
          if (x < this.R || x > this.W - this.R) vx = -vx;
          if (y < this.R || y > this.H - this.R) vy = -vy;


          // Update position
          x += vx * dt;
          y += vy * dt;

          // Apply friction
          vx *= 0.99;
          vy *= 0.99;


          // Collision with other balls
          for (const other of this.balls) {
            if (other === ball) continue;
            const dx = other.x - x;
            const dy = other.y - y;
            const distSq = dx * dx + dy * dy;
            const radiusSum = 2 * this.R;

            if (distSq < radiusSum * radiusSum) {
              // Collision detected
              let nx = dx / distSq;
              let ny = dy / distSq;

              // Calculate new velocities based on conservation of momentum and kinetic energy
              let m1 = 1;
              let m2 = 1;
              let v1x = vx * m1;
              let v1y = vy * m1;
              let v2x = other.vx * m2;
              let v2y = other.vy * m2;

              let newV1x = (v1x * (m2 - m1) + 2 * v2x * m1) / (m1 + m2);
              let newV1y = (v1y * (m2 - m1) + 2 * v2y * m1) / (m1 + m2);
              let newV2x = (v2x * (m1 - m2) + 2 * v1x * m2) / (m1 + m2);
              let newV2y = (v2y * (m1 - m2) + 2 * v1y * m2) / (m1 + m2);

              vx = newV1x;
              vy = newV1y;
              other.vx = newV2x;
              other.vy = newV2y;
            }
          }


          ball.x = x;
          ball.y = y;
        }

        // Pockets (simplified) - check if center of ball is within pocket
        for (const ball of this.balls) {
          if (!ball.cue) continue;
          const pocketX = this.W / 2;
          const pocketY = this.H / 2;
          const pocketRadius = this.R;

          if (Math.abs(ball.x - pocketX) < pocketRadius && Math.abs(ball.y - pocketY) < pocketRadius) {
            ball.potted = true;
            ball.cue = false; // Remove cue from play
          } else {
            ball.potted = false;
          }
        }

      },
      state: function() {
        return this.balls.map(ball => ({ x: ball.x, y: ball.y, vx: ball.vx, vy: ball.vy, potted: ball.potted, cue: ball.cue }));
      },
      shoot: function(vx, vy) {
        for (let i = 0; i < this.balls.length; i++) {
          if (this.balls[i].cue) {
            this.balls[i].vx = vx;
            this.balls[i].vy = vy;
            break;
          }
        }
      },
      pause: function() {
        requestAnimationFrame(null); // Pause the animation loop
      },
      resume: function() {
        requestAnimationFrame(this.step.bind(this)); // Resume the animation loop
      }
    };

    sim.reset([{x: 50, y: 50, vx: 2, vy: 3, cue: true}, {x: 300, y: 200, vx: -1, vy: -2, cue: false}, {x: 600, y: 400, vx: 1, vy: 1, cue: false}]);
    let isPaused = false;

    canvas.addEventListener('mousedown', function(e) {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Find the cue ball
      let cueBall = null;
      for (let i = 0; i < sim.balls.length; i++) {
        if (sim.balls[i].cue) {
          const distSq = Math.pow(mouseX - sim.balls[i].x, 2) + Math.pow(mouseY - sim.balls[i].y, 2);
          if (distSq < 100) {  // Adjust radius as needed
            cueBall = sim.balls[i];
            break;
          }
        }
      }

      if (cueBall) {
        sim.shoot(mouseX - rect.left - sim.W/2, mouseY - rect.top - sim.H/2); //Convert mouse to world coords
      }
    });


    canvas.addEventListener('mousemove', function(e) {
      const rect = canvas.getBoundingClientRect();
      let cueBall = null;

        for (let i = 0; i < sim.balls.length; i++) {
          if (sim.balls[i].cue) {
            const distSq = Math.pow(e.clientX - rect.left - sim.W/2 - sim.balls[i].x, 2) + Math.pow(e.clientY - rect.top - sim.H/2 - sim.balls[i].y, 2);
            if (distSq < 100) {  // Adjust radius as needed
              cueBall = sim.balls[i];
              break;
            }
          }
        }

      if (cueBall){
        let dx = e.clientX - rect.left - sim.W/2 - sim.balls[0].x; // Calculate drag direction
        let dy = e.clientY - rect.top - sim.H/2 - sim.balls[0].y;
          // Draw aim line
           ctx.beginPath();
           ctx.moveTo(rect.left + sim.W/2, rect.top + sim.H/2);
           ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
           ctx.strokeStyle = 'white';
           ctx.lineWidth = 2;
           ctx.stroke();

      }
    });


    canvas.addEventListener('mouseup', function() {
        isPaused = true; // Pause to allow for state capture
        sim.resume();
    })



    sim.resume();
  </script>
</body>
